using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    #region CalculateTotal – DataRow tests

    [TestMethod]
    [DataRow(10.0, 2, 0.10, 22.0,  DisplayName = "Basic 10% tax")]
    [DataRow(0.0,  5, 0.10, 0.0,   DisplayName = "Zero unit price")]
    [DataRow(25.0, 0, 0.08, 0.0,   DisplayName = "Zero quantity")]
    [DataRow(9.99, 1, 0.0,  9.99,  DisplayName = "No tax")]
    [DataRow(50.0, 3, 1.0,  300.0, DisplayName = "100% tax rate")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    public void CalculateTotal_NegativeQuantity_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, -1, 0.1m));
    }

    [TestMethod]
    public void CalculateTotal_NegativeUnitPrice_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(-5m, 2, 0.1m));
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Tax rate below zero")]
    [DataRow(1.01,  DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidTaxRate_ThrowsArgumentOutOfRangeException(double taxRate)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, 1, (decimal)taxRate));
    }

    #endregion

    #region ApplyDiscount – DataRow tests

    [TestMethod]
    [DataRow(100.0, 10.0, 90.0,  DisplayName = "10% off 100")]
    [DataRow(200.0, 25.0, 150.0, DisplayName = "25% off 200")]
    [DataRow(50.0,  0.0,  50.0,  DisplayName = "No discount")]
    [DataRow(80.0,  100.0, 0.0,  DisplayName = "100% discount")]
    [DataRow(49.99, 50.0, 24.995, DisplayName = "Fractional result")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.0,  DisplayName = "Discount below zero")]
    [DataRow(100.01, DisplayName = "Discount above 100")]
    public void ApplyDiscount_InvalidDiscountPercent_ThrowsArgumentOutOfRangeException(
        double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    #endregion

    #region CalculateTotal – DynamicData tests

    public static IEnumerable<object[]> BulkOrderTestData
    {
        get
        {
            yield return [99.99m,  100, 0.07m,  10_698.93m]; // large quantity
            yield return [0.01m, 1000, 0.05m,      10.50m];  // tiny price, high quantity
            yield return [999.99m,   1, 0.15m,  1_149.9885m]; // high price, single item
        }
    }

    [TestMethod]
    [DynamicData(nameof(BulkOrderTestData))]
    public void CalculateTotal_BulkOrders_ReturnsExpectedTotal(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> GetDiscountChainTestData()
    {
        // Applying successive discounts to a base price
        yield return [500m,  new[] { 10m, 20m },  360m];
        yield return [1000m, new[] { 50m },        500m];
        yield return [250m,  new[] { 0m, 0m, 0m }, 250m]; // no-op discounts
    }

    [TestMethod]
    [DynamicData(nameof(GetDiscountChainTestData), DynamicDataSourceType.Method)]
    public void ApplyDiscount_ChainedDiscounts_ReturnsExpectedFinalPrice(
        decimal startingPrice, decimal[] discounts, decimal expected)
    {
        var price = startingPrice;
        foreach (var discount in discounts)
        {
            price = _calculator.ApplyDiscount(price, discount);
        }

        Assert.AreEqual(expected, price);
    }

    #endregion
}

